package com.ksh321.songrecord.api.operations;
import org.springframework.core.env.Environment;
/** v1 deployment limits; raising schema/runtime ceilings requires a separately reviewed migration. */
public record OperationsPolicy(int betaAccounts,int pinnedLimit,long personalBytes,long globalBytes,long dailyBytes,int urlsPerMinute,int uploadConcurrency,long temporaryBytes,int workerConcurrency,int workerSeconds) {
 public OperationsPolicy { if(betaAccounts<1||betaAccounts>20||pinnedLimit<1||pinnedLimit>10||personalBytes<1||personalBytes>1000000000L||globalBytes<1||globalBytes>20000000000L||dailyBytes<1||dailyBytes>104857600L||urlsPerMinute<1||urlsPerMinute>10||uploadConcurrency<1||uploadConcurrency>2||temporaryBytes<1||temporaryBytes>536870912L||workerConcurrency<1||workerConcurrency>2||workerSeconds<1||workerSeconds>60)throw new IllegalArgumentException("OPERATIONS_POLICY_INVALID: values suppressed"); }
 public static OperationsPolicy defaults(){return new OperationsPolicy(20,10,1000000000L,20000000000L,104857600L,10,2,536870912L,2,60);}
 public static OperationsPolicy from(Environment e){var d=defaults();var p="songrecord.operations.";return new OperationsPolicy(e.getProperty(p+"beta-accounts",Integer.class,d.betaAccounts),e.getProperty(p+"pinned-limit",Integer.class,d.pinnedLimit),e.getProperty(p+"personal-bytes",Long.class,d.personalBytes),e.getProperty(p+"global-bytes",Long.class,d.globalBytes),e.getProperty(p+"daily-upload-bytes",Long.class,d.dailyBytes),e.getProperty(p+"urls-per-minute",Integer.class,d.urlsPerMinute),e.getProperty(p+"upload-concurrency",Integer.class,d.uploadConcurrency),e.getProperty(p+"temporary-bytes",Long.class,d.temporaryBytes),e.getProperty(p+"worker-concurrency",Integer.class,d.workerConcurrency),e.getProperty(p+"worker-seconds",Integer.class,d.workerSeconds));}
}
